{"script":"() => {
  const nutrition = document.querySelector('[id*="nutrition"]');
  const facts = document.querySelector('.mm-recipes-nutrition-facts');
  // Try to find calories
  const allElements = document.querySelectorAll('*');
  const results = [];
  for (const el of allElements) {
    const txt = el.textContent || '';
    if (el.children.length === 0 && txt.match(/calor/i)) {
      results.push({tag: el.tagName, text: txt.substring(0, 100), className: el.className});
    }
  }
  return results.slice(0, 20);
}"}

